// main/almanac_tables.h — calendar lookup tables for the almanac engine ([PURE], host-testable).
//
// almanac_tables.c is generated by tools/almanac/gen_tables.mjs from an independent calendar
// library; never edit it by hand. The supported range is 1900-01-31 .. 2100-12-31.
#pragma once

#include <stdint.h>

#define ALMANAC_YEAR_MIN 1900
#define ALMANAC_YEAR_MAX 2100
#define ALMANAC_LUNAR_YEAR_COUNT (ALMANAC_YEAR_MAX - ALMANAC_YEAR_MIN + 1)

// One lunar year. A lunar year starts on the spring festival (正月初一) of the given civil year.
//   big_bits bit i (0..11): lunar month i+1 has 30 days (1) or 29 days (0);
//   big_bits bit 12: the leap month (leap_month, 0 = none) has 30 days.
typedef struct {
    uint8_t spring_month;
    uint8_t spring_day;
    uint8_t leap_month;
    uint16_t big_bits;
} almanac_lunar_year_t;

extern const almanac_lunar_year_t almanac_lunar_years[ALMANAC_LUNAR_YEAR_COUNT];

// The twelve 节 (odd solar terms) of each civil year, in calendar order:
// 小寒 立春 惊蛰 清明 立夏 芒种 小暑 立秋 白露 寒露 立冬 大雪. Whole-day resolution, UTC+8.
typedef struct {
    uint8_t month[12];
    uint8_t day[12];
} almanac_jie_year_t;

extern const almanac_jie_year_t almanac_jie_years[ALMANAC_LUNAR_YEAR_COUNT];
